import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

solutions = []
limit = 10

for x1 in range(1, limit + 1):
    for x3 in range(1, limit + 1):
        # The condition for n=3 is: x3*x1 + x3 + x1 = x2^2
        R = x3 * x1 + x3 + x1

        if is_perfect_square(R):
            x2 = int(math.sqrt(R))
            solutions.append({'x1': x1, 'x2': x2, 'x3': x3})

print("Solutions found for n=3 (x1, x2, x3) where 1 <= x1, x3 <= 10:")
if solutions:
    for sol in solutions:
        print(f"x1={sol['x1']}, x2={sol['x2']}, x3={sol['x3']}")
else:
    print("No solutions found in the given range.")

