def check_sequence(x1, x2, max_len=6):
    """Checks sequence length starting with x1, x2."""
    sequence = [x1, x2]
    for i in range(2, max_len):
        xi_minus_1 = sequence[i-2]
        xi = sequence[i-1]

        # Check the condition for x_{i+1}: (x_{i+1}+1)(x_{i-1}+1) = x_i^2 + 1
        # x_{i+1} = (x_i^2 + 1) / (x_{i-1} + 1) - 1

        numerator = xi**2 + 1
        denominator = xi_minus_1 + 1

        if numerator % denominator != 0:
            return len(sequence) # Sequence terminates here

        x_i_plus_1 = (numerator // denominator) - 1

        if x_i_plus_1 <= 0:
            return len(sequence) # Must be positive integers

        sequence.append(x_i_plus_1)

    return len(sequence)

# Search for sequences of length n >= 5 using small starting values
# Bounds: x1, x2 <= 10
max_start = 10
results = {}

for x1 in range(1, max_start + 1):
    for x2 in range(1, max_start + 1):
        length = check_sequence(x1, x2)
        if length >= 5:
            results[(x1, x2)] = length

print(f"Sequences found of length >= 5 for x1, x2 <= {max_start}: {results}")
if not results:
    print("No sequences of length 5 or greater found in the tested range.")

def solve_sequence(x1, x2, max_n=5):
    X = [x1, x2]
    for i in range(2, max_n):
        # Calculate x_{i+1} using x_i and x_{i-1}
        xi = X[i-1]
        xi_minus_1 = X[i-2]

        numerator = xi**2 + 1
        denominator = xi_minus_1 + 1

        if numerator % denominator != 0:
            return None # Not an integer sequence

        next_x = (numerator // denominator) - 1

        if next_x <= 0:
            return None # Must be positive integers

        X.append(next_x)
    return X

# Systematic search for n=5
# Testing a relatively small initial range based on the existing solution (4, 33)
# We test x1 up to 10, and x2 up to 50, as sequences grow very fast.
N_MAX = 5
found_n5 = []
for x1 in range(1, 11):
    for x2 in range(1, 51):
        sequence = solve_sequence(x1, x2, N_MAX)
        if sequence:
            found_n5.append(sequence)

print(f"Found {len(found_n5)} sequences of length 5 or more in the search range.")
